export const canonicalBudgetGeneratorSource = "import assert from \"node:assert/strict\";\nimport { createHash } from \"node:crypto\";\nimport { existsSync, lstatSync, readFileSync, readdirSync, writeFileSync } from \"node:fs\";\nimport { mkdir } from \"node:fs/promises\";\nimport { join, relative } from \"node:path\";\nimport { gzipSync } from \"node:zlib\";\nimport { Database } from \"bun:sqlite\";\n\nconst root = import.meta.dir;\nconst output = join(root, \"capture1\");\nconst hash = (value: string | Uint8Array) => createHash(\"sha256\").update(value).digest(\"hex\");\nassert.equal(Bun.version, \"1.3.14\");\nassert.equal(lstatSync(root).mode & 0o777, 0o700);\nassert.equal(existsSync(output), false, \"Never overwrite an archived capture.\");\nconst definitions = {\n  43: { sourceCommit: \"97cebc44ecd2d27b8c0b6399b0814b1993d94fc1\", sourceTree: \"afb3340a1ed83b7735538aad955ad00d178dc116\",\n    sourceHashes: { \"src/storage/state-store.ts\": \"cfe045e01bd47585a45596b9e163f5562e25aa800bdd82f4fc1df0155eb55e31\",\n      \"package.json\": \"417a70d8cd6287b45f53e667603903a86388d9f186266326f1197a94b3202088\",\n      \"bun.lock\": \"db7ab88639f59ec431129416a31bb4de4ef4098d21c065d0be40d272019e46b5\" } },\n  45: { sourceCommit: \"5c5c02ee5964167fb85e92da53cdb80c87991890\", sourceTree: \"3f226e97912b667b67eea29a5f2ec66fe6f071da\",\n    sourceHashes: { \"src/storage/state-store.ts\": \"97977822058e5adeaecdd9d455f9169f102e2a7c5e478d643e98fe492028b26a\",\n      \"package.json\": \"a00f95f903852c2ba1b844b87a2061c083cfae4a29bc50262f5bbf64d17445ba\",\n      \"bun.lock\": \"39bdff36e30b4af4dd4eecb060b23c742d2b0111b983d4a9d63b06cbc80a69ff\" } },\n} as const;\nconst dependencies = { \"@hraness/oh\": \"0.2.7\", \"@openai/codex\": \"0.153.2\", convex: \"1.45.0\", effect: \"3.22.1\", zod: \"4.4.3\" };\nconst snapshot = (path: string) => {\n  const db = new Database(path, { create: false, strict: true });\n  db.exec(\"PRAGMA query_only=ON\");\n  try {\n    const schema = db.query(\"SELECT type,name,tbl_name,sql FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name\").all();\n    const tables = db.query(\"SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name\").all() as { name: string }[];\n    assert.ok(tables.length <= 256);\n    const rows: Record<string, unknown[]> = {};\n    for (const { name } of tables) {\n      assert.match(name, /^[a-zA-Z0-9_]+$/);\n      rows[name] = db.query(`SELECT * FROM \"${name}\"`).all().sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b)));\n      assert.ok(rows[name].length <= 4096);\n    }\n    const result = { userVersion: db.query(\"PRAGMA user_version\").get(), schema, rows,\n      foreignKeyCheck: db.query(\"PRAGMA foreign_key_check\").all(), inspectionChanges: db.query(\"SELECT total_changes() AS count\").get() };\n    assert.deepEqual(result.foreignKeyCheck, []);\n    assert.deepEqual(result.inspectionChanges, { count: 0 });\n    assert.ok(Buffer.byteLength(JSON.stringify(result)) < 8 * 1024 * 1024);\n    return result;\n  } finally { db.close(false); }\n};\nawait mkdir(output, { mode: 0o700 });\nconst generatorSource = readFileSync(import.meta.path, \"utf8\");\nlet original43: Uint8Array | undefined;\nlet retained43: Record<string, unknown> | undefined;\nconst summaries = [];\nfor (const version of [43, 45] as const) {\n  const sourceRoot = join(root, `canonical${version}`);\n  const definition = definitions[version];\n  for (const [path, expected] of Object.entries(definition.sourceHashes)) assert.equal(hash(readFileSync(join(sourceRoot, path))), expected);\n  for (const [name, expected] of Object.entries(dependencies)) assert.equal(JSON.parse(readFileSync(join(sourceRoot, \"node_modules\", name, \"package.json\"), \"utf8\")).version, expected);\n  const sourceFiles: { path: string; sha256: string }[] = [];\n  function visit(directory: string) {\n    for (const entry of readdirSync(directory, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {\n      const path = join(directory, entry.name);\n      if (entry.isDirectory()) visit(path);\n      else if (entry.isFile()) sourceFiles.push({ path: relative(sourceRoot, path), sha256: hash(readFileSync(path)) });\n      else throw new Error(\"Unexpected archived source entry.\");\n    }\n  }\n  visit(join(sourceRoot, \"src\"));\n  const { StateStore } = await import(`./canonical${version}/src/storage/state-store`);\n  const { initializeStatePaths, resolveStatePaths } = await import(`./canonical${version}/src/storage/paths`);\n  const directory = join(output, `canonical${version}`);\n  await mkdir(directory, { mode: 0o700 });\n  const paths = resolveStatePaths({ rootDirectory: join(directory, \"state\") });\n  await initializeStatePaths(paths);\n  if (version === 45) {\n    assert.ok(original43);\n    writeFileSync(paths.database, original43, { mode: 0o600, flag: \"wx\" });\n    assert.deepEqual(snapshot(paths.database).userVersion, { user_version: 43 });\n  }\n  const clock = { now: version * 1000 };\n  const store = new StateStore(paths, { now: () => clock.now });\n  const sessionInput = (profileId: string, title: string, suffix: string) => ({ profileId, provider: \"codex\" as const,\n    providerThreadId: `canonical-budget-synthetic-${suffix}`, providerAccountKey: \"v1:codex:\" + hash(\"canonical-budget@example.com\"),\n    title, preset: \"high\" as const, fastEnabled: false, state: \"idle\" as const });\n  let retained: Record<string, unknown>;\n  if (version === 43) {\n    const created = store.createProfile(\"Canonical budget synthetic account\");\n    const advanced = store.nextProfileGeneration(created.id);\n    assert.equal(store.setProfileState(advanced.id, advanced.processGeneration, \"signed_in\", { email: \"canonical-budget@example.com\", plan: \"Plus\" }), true);\n    const profile = store.requireProfile(advanced.id);\n    assert.equal(store.allocateNextUsageRevision(profile.id), 1);\n    const session = store.upsertProviderSession(sessionInput(profile.id, \"Canonical43 transcript repair source\", \"transcript\"));\n    const attachments = {\n      pending: [{ byteLength: 4, canonicalMediaType: \"text/plain\", digest: \"c\".repeat(64), mediaType: \"text/plain\", name: \"pre-release-safe.txt\" }],\n      dispatched: [{ byteLength: 4, canonicalMediaType: \"text/plain\", digest: \"d\".repeat(64), mediaType: \"text/plain\", name: \"pre-release-dispatched.txt\" }],\n      collisions: [\"collision-one.txt\", \"collision-two.txt\", \"same�name.txt\"].map(name => ({ byteLength: 4, canonicalMediaType: \"text/plain\", digest: \"f\".repeat(64), mediaType: \"text/plain\", name })),\n      cancelled: [{ byteLength: 4, canonicalMediaType: \"text/plain\", digest: \"e\".repeat(64), mediaType: \"text/plain\", name: \"cancelled-v43.txt\" }],\n    };\n    const queues: Record<string, unknown> = {};\n    for (const [index, [kind, storedAttachments]] of Object.entries(attachments).entries()) {\n      const messages = { pending: \"pre-release pending queue\", dispatched: \"pre-release effect-crossed queue\", collisions: \"preserve every colliding position\", cancelled: \"must be scrubbed after cancellation repair\" };\n      const queue = store.enqueueIdempotent({ sessionId: session.id, profileGeneration: profile.processGeneration,\n        idempotencyKey: `43000000-0000-4000-8000-${String(index + 10).padStart(12, \"0\")}`, message: messages[kind as keyof typeof messages],\n        attachments: storedAttachments.map(({ canonicalMediaType: _canonical, ...ref }) => ref), storedAttachments });\n      if (kind === \"dispatched\") assert.equal(store.transitionQueue(queue.id, \"pending\", \"dispatching\"), true);\n      queues[kind] = store.requireQueue(queue.id);\n    }\n    const budgetSession = store.upsertProviderSession(sessionInput(profile.id, \"Canonical43 existing budget\", \"budget\"));\n    const limitedSession = store.upsertProviderSession(sessionInput(profile.id, \"Canonical43 already limited\", \"limited\"));\n    for (let i = 0; i < 4; i++) store.bumpAutorespondCounter(limitedSession.id);\n    const historical = store.enqueueIdempotent({ sessionId: budgetSession.id, profileGeneration: profile.processGeneration,\n      message: \"Synthetic historical human continuation\", actor: \"human\", idempotencyKey: \"43000000-0000-4000-8000-000000000099\" });\n    assert.equal(store.transitionQueue(historical.id, \"pending\", \"dispatching\"), true);\n    assert.equal(store.transitionQueue(historical.id, \"dispatching\", \"applied\"), true);\n    const historicalEvent = store.finalizeSessionUserMessageSource({ sessionId: budgetSession.id, sourceKind: \"queue\", sourceId: historical.id, turnId: \"synthetic-turn\" });\n    assert.equal(historicalEvent?.body.type, \"user_message\");\n    retained = { profile, session, attachments, queues, budgetSession, limitedSession, historicalSourceId: historical.id, historicalEvent };\n    retained43 = retained;\n  } else {\n    assert.ok(retained43);\n    const budgetSession = retained43.budgetSession as { id: string; profileId: string };\n    assert.equal(store.readAutorespondBudgets(budgetSession.id).consecutive, 3);\n    assert.equal(store.readAutorespondBudgetHistoryAvailableAt(budgetSession.id), 86_445_000);\n    clock.now = 90_000_000;\n    assert.equal(store.readAutorespondBudgetHistoryAvailableAt(budgetSession.id), null);\n    store.resetAutorespondCounter(budgetSession.id);\n    const freshSession = store.upsertProviderSession(sessionInput(budgetSession.profileId, \"Canonical45 fresh budget\", \"fresh45\"));\n    const publicId = \"45000000-0000-4000-8000-000000000001\";\n    store.admitInteraction({ publicId, sessionId: freshSession.id,\n      authority: { profileId: freshSession.profileId, processGeneration: 1, connectionId: \"45000000-0000-4000-8000-999999999999\",\n        requestId: { type: \"string\", value: publicId }, method: \"item/commandExecution/requestApproval\", requestDigest: \"a\".repeat(64),\n        threadId: freshSession.providerThreadId, turnId: null, itemId: null, approvalId: null },\n      kind: \"command_approval\", blocking: true, display: { kind: \"command_approval\", summary: \"Review synthetic command\", reason: null,\n        commandClass: \"test\", workingDirectory: null, availableDecisions: [\"once\", \"decline\", \"cancel\"] } });\n    assert.deepEqual(store.reserveAutorespondBudget({ sessionId: freshSession.id, sourceId: publicId, sourceKind: \"protocol\", expectedMode: \"auto:all\" }), { state: \"reserved\" });\n    assert.deepEqual(store.readAutorespondBudgets(freshSession.id), { consecutive: 1, lastHour: 1, lastDay: 1 });\n    retained = { ...retained43, freshSession, reservationSourceId: publicId, legacyAvailableAt: 86_445_000 };\n  }\n  const finalSnapshot = snapshot(paths.database);\n  assert.deepEqual(finalSnapshot.userVersion, { user_version: version });\n  store.close();\n  const reopened = new StateStore(paths, { now: () => clock.now });\n  assert.deepEqual(snapshot(paths.database), finalSnapshot);\n  reopened.close();\n  const checkpoint = new Database(paths.database, { create: false, strict: true });\n  const checkpointResult = checkpoint.query(\"PRAGMA wal_checkpoint(TRUNCATE)\").get();\n  checkpoint.close(false);\n  assert.equal((checkpointResult as { busy: number }).busy, 0);\n  const beforeReadonly = hash(readFileSync(paths.database));\n  const readonly = new StateStore(paths, { readonly: true });\n  assert.deepEqual(snapshot(paths.database), finalSnapshot);\n  readonly.close();\n  const bytes = readFileSync(paths.database);\n  assert.equal(hash(bytes), beforeReadonly);\n  const metadata = { ...definition, schemaVersion: version, sourceManifestSha256: hash(JSON.stringify(sourceFiles)), sourceFileCount: sourceFiles.length,\n    generatorSha256: hash(generatorSource), bunVersion: Bun.version, dependencies, fixedTime: clock.now,\n    predecessorDatabaseSha256: version === 45 ? hash(original43!) : null,\n    provenance: { syntheticControlPlaneOnly: true, archivedPublicApisOnly: true, nativeProviderEffects: 0, networkEffects: 0,\n      rawSqlRowOrSchemaWrites: false, randomizedIdentifiers: true, writableReopenUnchanged: true, readonlyReopenUnchanged: true,\n      readonlyDatabaseHashUnchanged: true, originalUnsafeNamesOrCancelledPendingRows: false, currentMergedAdmissionClaim: false },\n    databaseSha256: hash(bytes), databaseBytes: bytes.length, checkpointResult, retained, snapshot: finalSnapshot };\n  const text = JSON.stringify(metadata);\n  for (const forbidden of [root, \"/Users/\", \"/private/\", \"/tmp/\", \"/home/\", \"/Volumes/\"]) {\n    assert.equal(text.includes(forbidden), false); assert.equal(bytes.includes(Buffer.from(forbidden)), false);\n  }\n  writeFileSync(join(directory, \"state.sqlite.gz\"), gzipSync(bytes), { mode: 0o600, flag: \"wx\" });\n  writeFileSync(join(directory, \"fixture.json\"), JSON.stringify(metadata, null, 2) + \"\\n\", { mode: 0o600, flag: \"wx\" });\n  writeFileSync(join(directory, \"source-manifest.json\"), JSON.stringify(sourceFiles, null, 2) + \"\\n\", { mode: 0o600, flag: \"wx\" });\n  if (version === 43) original43 = Uint8Array.from(bytes);\n  for (const [path, expected] of Object.entries(definition.sourceHashes)) assert.equal(hash(readFileSync(join(sourceRoot, path))), expected);\n  summaries.push({ version, sourceCommit: definition.sourceCommit, databaseSha256: hash(bytes), databaseBytes: bytes.length,\n    sourceManifestSha256: metadata.sourceManifestSha256, sourceFileCount: sourceFiles.length,\n    sessions: finalSnapshot.rows.sessions.length, queues: finalSnapshot.rows.queue_entries.length, archivedReopensUnchanged: true });\n}\nconsole.log(JSON.stringify({ generatorSha256: hash(generatorSource), summaries }));\n";

const compressedImages = "";

export function canonicalBudgetDatabaseBytes(version: 43 | 45): Uint8Array {
  const images = gunzipSync(Buffer.from(compressedImages, "base64"));
  let offset = 0;
  let selected: Uint8Array | undefined;
  for (const candidate of [43, 45] as const) {
    const fixture = canonicalBudgetFixtures[candidate];
    const bytes = images.subarray(offset, offset + fixture.databaseBytes);
    if (createHash("sha256").update(bytes).digest("hex") !== fixture.databaseSha256) {
      throw new Error("Canonical budget fixture integrity mismatch.");
    }
    if (candidate === version) selected = Uint8Array.from(bytes);
    offset += fixture.databaseBytes;
  }
  if (offset !== images.length || selected === undefined) throw new Error("Canonical budget fixture framing mismatch.");
  return selected;
}
